import { formatPersianDate } from '../utils/persianDate'
import { useEffect, useState } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { useSelector } from 'react-redux'
import { useSearchParams } from 'react-router-dom'
import { FiAlertCircle, FiPlus, FiRefreshCw, FiRotateCcw, FiX } from 'react-icons/fi'
import { toast } from 'sonner'
import JalaliDateInput from '../components/JalaliDateInput'
import SearchableSelect from '../components/SearchableSelect'
import { api, getErrorMessage, unwrap } from '../services/api'
import DataExportActions from '../components/DataExportActions'
import { fetchAllPages } from '../utils/fetchAllPages'

const localToday = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
}
const faNumber = (value) => new Intl.NumberFormat('fa-IR').format(Number(value || 0))
const money = (value) => `${new Intl.NumberFormat('fa-IR').format(BigInt(value || 0))} ریال`
const jalali = (value) => value ? formatPersianDate(`${String(value).slice(0, 10)}T12:00:00`) : '—'
const asciiDigits = (value) => String(value || '').replace(/[۰-۹٠-٩]/g, d => String('۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩'.indexOf(d) % 10))
const formatAmount = (value) => {
  const digits = asciiDigits(value).replace(/[^0-9]/g, '');
  return digits ? new Intl.NumberFormat('en-US').format(BigInt(digits)) : ''
}
const directions = {
  RECEIPT: { title: 'دریافت وجه', short: 'رسید دریافت', endpoint: 'receipt', positive: 'دریافت' },
  PAYMENT: { title: 'پرداخت وجه', short: 'سند پرداخت', endpoint: 'payment', positive: 'پرداخت' }
}
const methods = [
  { value: 'CASH', label: 'نقدی' },
  { value: 'PETTY_CASH', label: 'تنخواه' },
  { value: 'BANK_TRANSFER', label: 'انتقال بانکی' },
  { value: 'CHEQUE', label: 'چک' },
  { value: 'OTHER', label: 'سایر' }
]
const receiveMethods = [
  { value: 'CASH', label: 'نقدی' },
  { value: 'BANK_TRANSFER', label: 'انتقال بانکی' },
  { value: 'CHEQUE', label: 'چک' },
  { value: 'OTHER', label: 'سایر' },
  { value: 'PETTY_CASH', label: 'تنخواه' }
]
const chequeStatuses = {
  HELD: 'نزد صندوق',
  IN_COLLECTION: 'در جریان وصول',
  COLLECTED: 'وصول‌شده',
  ISSUED: 'صادرشده',
  ISSUED: 'صادرشده',
  CLEARED: 'وصول‌شده',
  RETURNED: 'برگشت‌خورده',
  TRANSFERRED: 'واگذارشده به تأمین‌کننده'
}

function ChequeManagementView({ direction, rows, pagination, loading, error, onRefresh, onPageChange, setTab, canRead, onCompanyAction, companyActionPending, loadExportRows }) {
  const incoming = direction === 'RECEIPT'
  const cheques = rows.filter(row => row.method === 'CHEQUE')
  const statusFor = row => row.cheque_status || null
  const count = (status) => pagination?.statusCounts?.[status] ?? cheques.filter(row => statusFor(row) === status).length
  const total = BigInt(pagination?.totalAmount || cheques.reduce((sum, row) => sum + BigInt(row.amount || 0), 0n))
  const chequeExportRows = cheques.map(row => [row.voucher_no,row.partner?.name||'—',row.method_details?.bankName||'—',row.method_details?.checkNumber||row.reference||'—',row.method_details?.sayadId||'—',jalali(row.method_details?.checkDate||row.entry_date),money(row.amount),chequeStatuses[statusFor(row)]||'وضعیت نامشخص'])
  return <section className="resource-page cash-voucher-page">
    <header className="cash-voucher-heading"><div className="cash-voucher-brand"><div className="cash-voucher-logo">ر</div><div><h1>دریافت و پرداخت</h1><p>مدیریت چرخهٔ چک‌ها</p></div></div><div className="cash-voucher-heading-actions"><DataExportActions title={incoming ? "چک‌های دریافتی" : "چک‌های پرداختی"} headers={["شماره سند","طرف حساب","بانک","شماره چک","شناسه صیادی","تاریخ چک","مبلغ","وضعیت"]} loadRows={loadExportRows}/><button className="btn btn-secondary" onClick={onRefresh} disabled={loading}><FiRefreshCw /> به‌روزرسانی</button></div></header>
    <nav className="cash-voucher-tabs" role="tablist" aria-label="عملیات مالی"><button role="tab" onClick={() => setTab('receipt')}>↓ دریافت</button><button role="tab" onClick={() => setTab('payment')}>↑ پرداخت</button><button role="tab" aria-selected={incoming} className={incoming ? 'active' : ''} onClick={() => setTab('incoming-cheques')}>▤ چک‌های دریافتی</button><button role="tab" aria-selected={!incoming} className={!incoming ? 'active' : ''} onClick={() => setTab('outgoing-cheques')}>▤ چک‌های پرداختی</button></nav>
    <div className="cash-preview-notice"><FiAlertCircle /><span>وصول یا برگشت هر چک، وضعیت دفتر چک و سند حسابداری مرتبط را هم‌زمان ثبت می‌کند.</span></div>
    <div className="cash-check-intro"><div><span className="eyebrow">دفتر چک‌ها</span><h2>{incoming ? 'چک‌های دریافت‌شده از مشتریان' : 'چک‌های صادرشده برای پرداخت'}</h2><p>{incoming ? 'چک دریافتی ابتدا نزد صندوق است؛ سپس به بانک تحویل می‌شود و بعد از تأیید بانک وصول‌شده محسوب می‌شود.' : 'چک پرداختی تا زمان تأیید بانک در وضعیت صادرشده می‌ماند.'}</p></div><span className="cash-check-total">جمع مبلغ <b>{money(total)}</b></span></div>
    <div className="cash-check-flow" aria-label="مراحل گردش چک">{(incoming ? [["نزد صندوق", "HELD"], ["در جریان وصول", "IN_COLLECTION"], ["وصول‌شده", "COLLECTED"], ["برگشت‌خورده", "RETURNED"]] : [["صادرشده", "ISSUED"], ["وصول‌شده", "CLEARED"], ["برگشت‌خورده", "RETURNED"]]).map(([label, status], index) => <span key={status} className={`cash-check-flow-step ${status === 'RETURNED' ? 'returned' : ''}`}><b>{faNumber(index + 1)}</b>{label}</span>)}</div>
    <div className="cash-check-stats"><div><span>همهٔ چک‌ها</span><b>{faNumber(pagination?.totalItems ?? cheques.length)}</b></div><div><span>{incoming ? 'نزد صندوق' : 'صادرشده'}</span><b>{faNumber(count(incoming ? 'HELD' : 'ISSUED'))}</b></div>{incoming && <div><span>در جریان وصول</span><b>{faNumber(count('IN_COLLECTION'))}</b></div>}<div><span>وصول‌شده</span><b>{faNumber(count(incoming ? 'COLLECTED' : 'CLEARED'))}</b></div><div><span>برگشت‌خورده</span><b>{faNumber(count('RETURNED'))}</b></div></div>
    <section className="cash-card cash-list"><div className="cash-list-heading"><h2>فهرست {incoming ? 'چک‌های دریافتی' : 'چک‌های پرداختی'}</h2><span>{faNumber(pagination?.totalItems ?? cheques.length)} مورد</span></div>{!canRead ? <div className="error-state"><FiAlertCircle /><strong>دسترسی به این بخش ندارید</strong></div> : loading ? <div className="loading-line" /> : error ? <div className="error-state"><FiAlertCircle />{error}</div> : <div className="table-scroll"><table className="data-table cash-check-table"><thead><tr><th>شماره سند</th><th>طرف‌حساب</th><th>بانک چک</th><th>شماره چک</th><th>شناسه صیادی</th><th>تاریخ چک</th><th>مبلغ</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>{cheques.map(row => { const status = statusFor(row); return <tr key={row.id}><td>{row.voucher_no}</td><td>{row.partner?.name || '—'}</td><td>{row.method_details?.bankName || '—'}</td><td>{row.method_details?.checkNumber || row.reference || '—'}</td><td>{row.method_details?.sayadId || '—'}</td><td>{jalali(row.method_details?.checkDate || row.entry_date)}</td><td className="number-cell">{money(row.amount)}</td><td><span className={`cash-check-status ${status || 'UNKNOWN'}`}>{status ? chequeStatuses[status] || status : 'ثبت قدیمی · وضعیت نامشخص'}</span></td><td>{row.is_company_cheque && status === 'ISSUED' ? <div className="cash-cheque-actions"><button className="btn btn-secondary" disabled={companyActionPending} onClick={() => onCompanyAction(row, 'clear')}>ثبت وصول</button><button className="btn btn-secondary" disabled={companyActionPending} onClick={() => onCompanyAction(row, 'return')}>ثبت برگشت</button></div> : row.is_company_cheque ? '—' : <button className="btn btn-secondary" disabled>{incoming ? (status === 'HELD' ? 'تحویل به بانک' : status === 'IN_COLLECTION' ? 'ثبت وصول' : 'عملیات') : (status === 'ISSUED' ? 'ثبت وصول چک' : 'عملیات')}</button>}</td></tr> })}{!cheques.length && <tr><td colSpan="9"><div className="empty-state">هنوز چکی ثبت نشده است.</div></td></tr>}</tbody></table></div>}<div className="table-footer"><span>صفحهٔ {faNumber(pagination?.page || 1)} از {faNumber(Math.max(1, pagination?.totalPages || 1))}</span><div className="pagination"><button disabled={(pagination?.page || 1) <= 1} onClick={() => onPageChange((pagination?.page || 1) - 1)}>صفحهٔ قبل</button><button disabled={(pagination?.page || 1) >= (pagination?.totalPages || 1)} onClick={() => onPageChange((pagination?.page || 1) + 1)}>صفحهٔ بعد</button></div></div></section>
  </section>
}

export default function CashVouchersPage() {
  const [searchParams, setSearchParams] = useSearchParams()
  const activeTab = searchParams.get('tab') || 'receipt'
  const direction = ['payment', 'outgoing-cheques'].includes(activeTab) || (activeTab === 'direct' && searchParams.get('returnTab') === 'payment') ? 'PAYMENT' : 'RECEIPT'
  const showChequeRegistry = ['incoming-cheques', 'outgoing-cheques'].includes(activeTab)
  const showSettlementPreview = searchParams.get('tab') === 'direct'
  const [directDate, setDirectDate] = useState(localToday())
  const [directAmount, setDirectAmount] = useState('')
  const [directCustomerId, setDirectCustomerId] = useState('')
  const [directSupplierId, setDirectSupplierId] = useState('')
  const [directDescription, setDirectDescription] = useState('')
  const [directReference, setDirectReference] = useState('')
  const [reverseDirectSelected, setReverseDirectSelected] = useState(null)
  const config = directions[direction]
  const methodOptions = direction === 'RECEIPT' ? receiveMethods : methods
  const user = useSelector(s => s.session.user)
  const isAdmin = user?.rolename?.toLowerCase() === 'مدیر سایت'
  const canRead = isAdmin || user?.permissions?.includes('financial.cash-vouchers.read')
  const canCreate = isAdmin || user?.permissions?.includes('financial.cash-vouchers.create')
  const canReverse = isAdmin || user?.permissions?.includes('financial.cash-vouchers.reverse')
  const [date, setDate] = useState(localToday())
  const [amount, setAmount] = useState('')
  const [treasuryId, setTreasuryId] = useState('')
  const [paymentTarget, setPaymentTarget] = useState('')
  const [partnerId, setPartnerId] = useState('')
  const [receiptCategory, setReceiptCategory] = useState('CUSTOMER_RECEIPT')
  const [otherRecipientPartnerId, setOtherRecipientPartnerId] = useState('')
  const [otherPaymentPartnerId, setOtherPaymentPartnerId] = useState('')
  const [method, setMethod] = useState('CASH')
  const [chequeSource, setChequeSource] = useState('COMPANY')
  const [customerChequeId, setCustomerChequeId] = useState('')
  const [customerChequeSearch, setCustomerChequeSearch] = useState('')
  const [companyCheckbookId, setCompanyCheckbookId] = useState('')
  const [companyCheckNumber, setCompanyCheckNumber] = useState('')
  const [companyCheckSearch, setCompanyCheckSearch] = useState('')
  const [checkDetails, setCheckDetails] = useState({ bankName: '', checkNumber: '', accountNumber: '', sayadId: '', checkDate: '', ownerName: '' })
  const [reference, setReference] = useState('')
  const [description, setDescription] = useState('')
  const [reverseSelected, setReverseSelected] = useState(null)
  const [reverseReason, setReverseReason] = useState('')
  const [reverseDate, setReverseDate] = useState(localToday())
  const [page, setPage] = useState(1)
  useEffect(() => setPage(1), [activeTab])
  const qc = useQueryClient()
  const optionsQuery = useQuery({ queryKey: ['cash-voucher-options'], queryFn: async () => {
    const fixed = unwrap(await api.get('/financial/cash-vouchers/options'))
    const treasuryAccounts = await fetchAllPages('/financial/cash-vouchers/options/treasury-accounts')
    const partners = await fetchAllPages('/financial/cash-vouchers/options/partners')
    const paymentAccounts = await fetchAllPages('/financial/cash-vouchers/options/payment-accounts')
    return { ...fixed, treasuryAccounts, partners, paymentAccounts }
  }, enabled: canRead })
  const listQuery = useQuery({ queryKey: ['cash-vouchers', direction, page], queryFn: async () => unwrap(await api.get(`/financial/cash-vouchers?direction=${direction}&page=${page}&limit=20`)), enabled: canRead })
  const chequeRegisterQuery = useQuery({ queryKey: ['cheque-register', direction, page], queryFn: async () => unwrap(await api.get(`/financial/cheque-register?direction=${direction}&page=${page}&limit=20`)), enabled: canRead && showChequeRegistry })
  const directOptionsQuery = useQuery({ queryKey: ['direct-settlement-options'], queryFn: async () => {
    const customers = await fetchAllPages('/financial/cash-vouchers/direct-settlements/options/customers')
    const suppliers = await fetchAllPages('/financial/cash-vouchers/direct-settlements/options/suppliers')
    return { customers, suppliers }
  }, enabled: canRead && showSettlementPreview })
  const directListQuery = useQuery({ queryKey: ['direct-settlements', page], queryFn: async () => unwrap(await api.get(`/financial/cash-vouchers/direct-settlements?page=${page}&limit=20`)), enabled: canRead && showSettlementPreview })
  const customerChequeStatus = 'HELD'
  const customerChequeQuery = useQuery({ queryKey: ['customer-cheques', customerChequeStatus, customerChequeSearch], queryFn: async () => fetchAllPages(`/financial/customer-cheques?status=${customerChequeStatus}&search=${encodeURIComponent(customerChequeSearch)}`), enabled: canRead && direction === 'PAYMENT' && method === 'CHEQUE' && chequeSource === 'CUSTOMER' && !showChequeRegistry && customerChequeSearch.trim().length >= 2 })
  const companyCheckbooksQuery = useQuery({ queryKey: ['company-checkbooks', 'all-options'], queryFn: async () => fetchAllPages('/financial/company-checkbooks'), enabled: canRead })
  const companyCheckNumberQuery = useQuery({ queryKey: ['company-checkbook-numbers', companyCheckbookId, companyCheckSearch], queryFn: async () => unwrap(await api.get(`/financial/company-checkbooks/${companyCheckbookId}/numbers?search=${encodeURIComponent(companyCheckSearch)}`)), enabled: canRead && direction === 'PAYMENT' && method === 'CHEQUE' && chequeSource === 'COMPANY' && Boolean(companyCheckbookId) })
  const options = optionsQuery.data || {}
  const treasuryAccounts = options.treasuryAccounts || []
  const paymentAccounts = options.paymentAccounts || []
  const categoryOptions = options.categories?.[direction] || []
  const selectedTreasury = treasuryAccounts.find(account => account.id === treasuryId)
  const heldCustomerCheques = customerChequeQuery.data || []
  const selectedCustomerCheque = heldCustomerCheques.find(cheque => String(cheque.id) === String(customerChequeId))
  const companyCheckbooks = companyCheckbooksQuery.data || []
  const selectedCompanyCheckbook = companyCheckbooks.find(book => String(book.id) === String(companyCheckbookId))
  const receiptPartners = (options.partners || []).filter(item => ['CUSTOMER', 'BOTH'].includes(item.partner_type))
  const receiptRecipients = (options.partners || []).filter(item => ['SUPPLIER', 'BOTH'].includes(item.partner_type))
  const create = useMutation({ mutationFn: async (payload) => unwrap(await api.post(`/financial/cash-vouchers/${config.endpoint}`, payload)), onSuccess: (result) => { toast.success(`${config.short} ثبت شد${result?.voucher_no ? ` · ${result.voucher_no}` : ''}`); qc.invalidateQueries({ queryKey: ['cash-vouchers', direction] }); qc.invalidateQueries({ queryKey: ['resource', '/financial/treasury/accounts'] }); resetForm() }, onError: e => toast.error(getErrorMessage(e)) })
  const reverse = useMutation({ mutationFn: async () => unwrap(await api.post(`/financial/cash-vouchers/${reverseSelected.id}/reverse`, { entryDate: reverseDate, reason: reverseReason.trim() })), onSuccess: (result) => { toast.success(`سند معکوس ثبت شد${result?.voucher_no ? ` · ${result.voucher_no}` : ''}`); qc.invalidateQueries({ queryKey: ['cash-vouchers'] }); qc.invalidateQueries({ queryKey: ['resource', '/financial/treasury/accounts'] }); setReverseSelected(null); setReverseReason('') }, onError: e => toast.error(getErrorMessage(e)) })
  const directCreate = useMutation({ mutationFn: async (payload) => unwrap(await api.post('/financial/cash-vouchers/direct-settlements', payload)), onSuccess: (result) => { toast.success(`تسویه مستقیم ثبت شد${result?.voucher_no ? ` · ${result.voucher_no}` : ''}`); qc.invalidateQueries({ queryKey: ['direct-settlements'] }); qc.invalidateQueries({ queryKey: ['resource', '/commercial/financial-balances?direction=PAYABLE'] }); qc.invalidateQueries({ queryKey: ['resource', '/commercial/financial-balances?direction=RECEIVABLE'] }); qc.invalidateQueries({ queryKey: ['purchase-invoices'] }); qc.invalidateQueries({ queryKey: ['sales-invoices'] }); setDirectAmount(''); setDirectCustomerId(''); setDirectSupplierId(''); setDirectDescription(''); setDirectReference(''); resetForm() }, onError: e => toast.error(getErrorMessage(e)) })
  const reverseDirect = useMutation({ mutationFn: async () => unwrap(await api.post(`/financial/cash-vouchers/direct-settlements/${reverseDirectSelected.id}/reverse`, { entryDate: reverseDate, reason: reverseReason.trim() })), onSuccess: (result) => { toast.success(`برگشت تسویه ثبت شد${result?.voucher_no ? ` · ${result.voucher_no}` : ''}`); qc.invalidateQueries({ queryKey: ['direct-settlements'] }); qc.invalidateQueries({ queryKey: ['resource', '/commercial/financial-balances?direction=PAYABLE'] }); qc.invalidateQueries({ queryKey: ['resource', '/commercial/financial-balances?direction=RECEIVABLE'] }); qc.invalidateQueries({ queryKey: ['purchase-invoices'] }); qc.invalidateQueries({ queryKey: ['sales-invoices'] }); setReverseDirectSelected(null); setReverseReason('') }, onError: e => toast.error(getErrorMessage(e)) })
  const customerChequeCreate = useMutation({ mutationFn: async ({ kind, id, payload }) => unwrap(await api.post(kind === 'receive' ? '/financial/customer-cheques' : `/financial/customer-cheques/${id}/transfer`, payload)), onSuccess: (result, variables) => { toast.success(variables.kind === 'receive' ? `چک دریافتی ثبت شد${result?.cheque_no ? ` · ${result.cheque_no}` : ''}` : `واگذاری چک ثبت شد${result?.transfer_no ? ` · ${result.transfer_no}` : ''}`); qc.invalidateQueries({ queryKey: ['customer-cheques'] }); qc.invalidateQueries({ queryKey: ['cheque-register'] }); qc.invalidateQueries({ queryKey: ['cash-vouchers', 'RECEIPT'] }); qc.invalidateQueries({ queryKey: ['cash-vouchers', 'PAYMENT'] }); resetForm() }, onError: e => toast.error(getErrorMessage(e)) })
  const issueCompanyCheque = useMutation({ mutationFn: async ({ id, payload }) => unwrap(await api.post(`/financial/company-checkbooks/${id}/issue`, payload)), onSuccess: result => { toast.success(`چک پرداختی صادر شد${result?.cheque_no ? ` · ${result.cheque_no}` : ''}`); qc.invalidateQueries({ queryKey: ['company-checkbook-numbers'] }); qc.invalidateQueries({ queryKey: ['company-cheques'] }); resetForm() }, onError: e => toast.error(getErrorMessage(e)) })
  const companyChequeAction = useMutation({ mutationFn: async ({ id, action }) => unwrap(await api.post(`/financial/company-cheques/${id}/${action}`, { entryDate: localToday(), description: action === 'clear' ? 'وصول چک پرداختی توسط بانک' : 'برگشت چک پرداختی و بازگشت بدهی به تأمین‌کننده' })), onSuccess: (_, variables) => { toast.success(variables.action === 'clear' ? 'وصول چک ثبت شد' : 'برگشت چک ثبت شد'); qc.invalidateQueries({ queryKey: ['company-cheques'] }); qc.invalidateQueries({ queryKey: ['cheque-register'] }); qc.invalidateQueries({ queryKey: ['resource', '/financial/treasury/accounts'] }) }, onError: e => toast.error(getErrorMessage(e)) })
  const resetForm = () => { setDate(localToday()); setAmount(''); setTreasuryId(''); setPaymentTarget(''); setPartnerId(''); setReceiptCategory('CUSTOMER_RECEIPT'); setOtherRecipientPartnerId(''); setOtherPaymentPartnerId(''); setMethod('CASH'); setChequeSource('COMPANY'); setCustomerChequeId(''); setCustomerChequeSearch(''); setCompanyCheckbookId(''); setCompanyCheckNumber(''); setCompanyCheckSearch(''); setCheckDetails({ bankName: '', checkNumber: '', accountNumber: '', sayadId: '', checkDate: '', ownerName: '' }); setReference(''); setDescription('') }
  const submit = (event) => {
    event.preventDefault()
    if (direction === 'RECEIPT') {
      const numericReceiptAmount = asciiDigits(amount).replace(/[^0-9]/g, '')
      if (method === 'OTHER') {
        if (!date || !partnerId || !otherRecipientPartnerId || !numericReceiptAmount || BigInt(numericReceiptAmount) <= 0n) { toast.error('مشتری پرداخت‌کننده، طلبکار و مبلغ را کامل کنید'); return }
        directCreate.mutate({ entryDate: date, amount: numericReceiptAmount, customerPartnerId: partnerId, supplierPartnerId: otherRecipientPartnerId, reference: reference.trim() || null, description: description.trim() || 'تسویهٔ مستقیم مشتری با تأمین‌کننده' })
        return
      }
      if (method !== 'CHEQUE' && (!date || !partnerId || !treasuryId || !numericReceiptAmount || BigInt(numericReceiptAmount) <= 0n)) { toast.error('مشتری، تاریخ، حساب دریافت و مبلغ را کامل کنید'); return }
      if (method !== 'CHEQUE') {
        create.mutate({ entryDate: date, amount: numericReceiptAmount, treasuryAccountId: treasuryId, category: receiptCategory, partnerId, method: method === 'PETTY_CASH' ? 'CASH' : method, methodDetails: null, reference: reference.trim() || null, description: description.trim() || 'دریافت از مشتری بابت فروش' })
        return
      }
      if (!date || !partnerId || !checkDetails.bankName || !checkDetails.checkDate || !checkDetails.checkNumber.trim() || !numericReceiptAmount || BigInt(numericReceiptAmount) <= 0n) { toast.error('مشتری، تاریخ، مشخصات ضروری چک و مبلغ را کامل کنید'); return }
      customerChequeCreate.mutate({ kind: 'receive', payload: { entryDate: date, amount: numericReceiptAmount, partnerId, bankName: checkDetails.bankName, checkNumber: checkDetails.checkNumber.trim(), checkDate: checkDetails.checkDate, accountNumber: checkDetails.accountNumber.trim() || null, sayadId: checkDetails.sayadId.trim() || null, description: description.trim() || 'دریافت چک از مشتری' } })
      return
    }
    const numericAmount = asciiDigits(amount).replace(/[^0-9]/g, '')
    if (method === 'CHEQUE' && chequeSource === 'CUSTOMER') {
      const [targetType, payeePartnerId] = paymentTarget.split(':')
      if (!customerChequeId || targetType !== 'PARTNER' || !payeePartnerId || !date) { toast.error('چک نزد صندوق، تأمین‌کننده و تاریخ سند را انتخاب کنید'); return }
      customerChequeCreate.mutate({ kind: 'transfer', id: customerChequeId, payload: { entryDate: date, payeePartnerId, reference: reference.trim() || null, description: description.trim() || 'واگذاری چک دریافتی به تأمین‌کننده' } })
      return
    }
    if (method === 'CHEQUE' && chequeSource === 'COMPANY') {
      const [targetType, payeePartnerId] = paymentTarget.split(':')
      if (!companyCheckbookId || !companyCheckNumber || targetType !== 'PARTNER' || !payeePartnerId || !date || !checkDetails.checkDate || !numericAmount || BigInt(numericAmount) <= 0n) { toast.error('دسته‌چک، شماره چک، تاریخ چک، مبلغ و تأمین‌کننده را کامل کنید'); return }
      issueCompanyCheque.mutate({ id: companyCheckbookId, payload: { checkNumber: companyCheckNumber, sayadId: checkDetails.sayadId.trim() || null, entryDate: date, checkDate: checkDetails.checkDate, amount: numericAmount, payeePartnerId, description: description.trim() || 'پرداخت به تأمین‌کننده با چک شرکت' } })
      return
    }
    if (method === 'OTHER') {
      const [targetType, supplierPartnerId] = paymentTarget.split(':')
      const payer = (options.partners || []).find(p => p.id === otherPaymentPartnerId)
      if (!date || targetType !== 'PARTNER' || !supplierPartnerId || !payer || !['CUSTOMER', 'BOTH'].includes(payer.partner_type) || !numericAmount || BigInt(numericAmount) <= 0n) { toast.error('مشتری پرداخت‌کننده، تأمین‌کننده و مبلغ را کامل کنید'); return }
      directCreate.mutate({ entryDate: date, amount: numericAmount, customerPartnerId: otherPaymentPartnerId, supplierPartnerId, reference: reference.trim() || null, description: description.trim() || 'تسویهٔ مستقیم مشتری با تأمین‌کننده' })
      return
    }
    if (!date || !numericAmount || BigInt(numericAmount) <= 0n || !treasuryId || !paymentTarget || description.trim().length < 2) { toast.error('فیلدهای ضروری را کامل کنید'); return }
    const [paymentTargetType, targetId] = paymentTarget.split(':')
    create.mutate({ entryDate: date, amount: numericAmount, treasuryAccountId: treasuryId, paymentTargetType, ...(paymentTargetType === 'ACCOUNT' ? { counterpartAccountId: targetId, partnerId: null } : { partnerId: targetId }), method: method === 'PETTY_CASH' ? 'CASH' : method, methodDetails: null, reference: reference.trim() || null, description: description.trim() })
  }
  const rows = listQuery.data?.items || []
  const directRows = directListQuery.data?.items || []
  const cashExportHeaders = showSettlementPreview ? ['شماره سند','تاریخ','مشتری','تأمین‌کننده','شرح','مبلغ','وضعیت'] : ['شماره سند','تاریخ','طرف حساب','حساب مقابل','خزانه','روش','شرح','مبلغ','وضعیت']
  const mapCashExportRows = source => showSettlementPreview ? source.map(row => [row.voucher_no,jalali(row.entry_date),row.customer?.name||'—',row.supplier?.name||'—',row.description||'—',money(row.amount),row.reverses_settlement_id?'سند معکوس':row.reversal?'برگشت شده':'ثبت‌شده']) : source.map(row => [row.voucher_no,jalali(row.entry_date),row.partner?.name||'—',row.reverses_voucher_id?'برگشت سند':direction==='PAYMENT'?[row.counterpartAccount?.name,row.partner?.name].filter(Boolean).join(' · ')||'—':categoryOptions.find(x=>x.value===row.category)?.label||row.category,row.treasuryAccount?.name||'—',row.method==='CASH'&&row.treasuryAccount?.account_type==='PETTY_CASH'?'تنخواه':methods.find(x=>x.value===row.method)?.label||row.method,row.description||'—',money(row.amount),row.reverses_voucher_id?'سند معکوس':row.reversal?'برگشت شده':'ثبت‌شده'])
  const loadCashExportRows = async () => mapCashExportRows(await fetchAllPages(showSettlementPreview ? '/financial/cash-vouchers/direct-settlements' : `/financial/cash-vouchers?direction=${direction}`))
  const directOptions = directOptionsQuery.data || { customers: [], suppliers: [] }
  const submitDirect = (event) => { event.preventDefault(); const numericAmount = asciiDigits(directAmount).replace(/[^0-9]/g, ''); if (!directDate || !numericAmount || BigInt(numericAmount) <= 0n || !directCustomerId || !directSupplierId || directDescription.trim().length < 2) { toast.error('فیلدهای ضروری را کامل کنید'); return } directCreate.mutate({ entryDate: directDate, amount: numericAmount, customerPartnerId: directCustomerId, supplierPartnerId: directSupplierId, reference: directReference.trim() || null, description: directDescription.trim() }) }

  const loadChequeExportRows = async () => (await fetchAllPages(`/financial/cheque-register?direction=${direction}`)).map(row => [row.voucher_no,row.partner?.name||'—',row.method_details?.bankName||'—',row.method_details?.checkNumber||row.reference||'—',row.method_details?.sayadId||'—',jalali(row.method_details?.checkDate||row.entry_date),money(row.amount),chequeStatuses[row.cheque_status]||'وضعیت نامشخص'])
  if (showChequeRegistry) return <ChequeManagementView direction={direction} rows={chequeRegisterQuery.data?.items || []} pagination={chequeRegisterQuery.data?.pagination} loading={chequeRegisterQuery.isLoading} error={chequeRegisterQuery.isError ? getErrorMessage(chequeRegisterQuery.error) : null} onRefresh={() => chequeRegisterQuery.refetch()} onPageChange={setPage} loadExportRows={loadChequeExportRows} setTab={tab => setSearchParams({ tab })} canRead={canRead} onCompanyAction={(row, action) => companyChequeAction.mutate({ id: row.id, action })} companyActionPending={companyChequeAction.isPending} />

  return (
    <section className="resource-page cash-voucher-page">
      <header className="cash-voucher-heading">
        <div className="cash-voucher-brand">
          <div className="cash-voucher-logo">ر</div>
          <div>
            <h1>دریافت و پرداخت</h1>
            <p>{showSettlementPreview ? 'تسویه مستقیم بدهی مشتری و تأمین‌کننده' : direction === 'RECEIPT' ? 'ثبت دریافت وجه' : 'ثبت پرداخت وجه'}</p>
          </div>
        </div>
        <div className="cash-voucher-heading-actions">
          <div className="cash-voucher-number">
            <span>شماره سند</span>
            <b>پس از ثبت صادر می‌شود</b>
          </div>
          {!showChequeRegistry && <DataExportActions title={showSettlementPreview ? "تسویه‌های مستقیم" : direction === "RECEIPT" ? "دریافت‌ها" : "پرداخت‌ها"} headers={cashExportHeaders} loadRows={loadCashExportRows}/>}<button className="btn btn-secondary" onClick={() => showSettlementPreview ? directListQuery.refetch() : listQuery.refetch()} disabled={showSettlementPreview ? directListQuery.isFetching : listQuery.isFetching}><FiRefreshCw /> به‌روزرسانی</button>
        </div>
      </header>
      <div className="cash-voucher-tabs" role="tablist" aria-label="عملیات مالی"><button role="tab" aria-selected={direction === 'RECEIPT'} className={direction === 'RECEIPT' ? 'active' : ''} onClick={() => { setMethod('CASH'); setPaymentTarget(''); setTreasuryId(''); setSearchParams({ tab: 'receipt' }) }}>↓ دریافت</button><button role="tab" aria-selected={direction === 'PAYMENT'} className={direction === 'PAYMENT' ? 'active' : ''} onClick={() => { setMethod('CASH'); setPaymentTarget(''); setTreasuryId(''); setSearchParams({ tab: 'payment' }) }}>↑ پرداخت</button><button role="tab" aria-selected={activeTab === 'incoming-cheques'} className={activeTab === 'incoming-cheques' ? 'active' : ''} onClick={() => setSearchParams({ tab: 'incoming-cheques' })}>▤ چک‌های دریافتی</button><button role="tab" aria-selected={activeTab === 'outgoing-cheques'} className={activeTab === 'outgoing-cheques' ? 'active' : ''} onClick={() => setSearchParams({ tab: 'outgoing-cheques' })}>▤ چک‌های پرداختی</button></div>
      <div className="cash-voucher-layout">
        {!showSettlementPreview ? <form className="cash-card cash-form" onSubmit={submit}>
          {direction === 'RECEIPT' ? <section className="cash-section"><div className="cash-section-title"><span>۱</span><b>طرف‌حساب و مشخصات سند</b></div><div className="cash-grid cash-grid-2"><label className="cash-field"><span>طرف‌حساب *</span><SearchableSelect required value={partnerId} onChange={e => setPartnerId(e.target.value)}><option value="">انتخاب مشتری</option>{receiptPartners.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</SearchableSelect></label><label className="cash-field"><span>تاریخ *</span><JalaliDateInput className="form-control" value={date} onChange={setDate} /></label></div></section> : <section className="cash-section"><div className="cash-section-title"><span>۱</span><b>پرداخت به / انتخاب حساب</b></div><div className="cash-grid cash-grid-2"><label className="cash-field"><span>پرداخت به *</span><SearchableSelect required value={paymentTarget} onChange={e => setPaymentTarget(e.target.value)}><option value="">انتخاب مقصد پرداخت</option><optgroup label="حساب‌های مالی">{paymentAccounts.map(account => <option key={account.id} value={`ACCOUNT:${account.id}`}>{account.account_path} · {account.code}</option>)}</optgroup><optgroup label="تأمین‌کنندگان">{(options.partners || []).filter(p => ['SUPPLIER', 'BOTH'].includes(p.partner_type)).map(p => <option key={p.id} value={`PARTNER:${p.id}`}>{p.name}</option>)}</optgroup></SearchableSelect></label><label className="cash-field"><span>تاریخ سند *</span><JalaliDateInput className="form-control" value={date} onChange={setDate} /></label></div></section>}
          <section className="cash-section">
            <div className="cash-section-title">
              <span>۲</span>
              <b>روش {config.positive}</b></div><div className={`cash-methods ${direction === 'RECEIPT' ? 'cash-methods-five' : ''}`}>{(direction === 'RECEIPT' ? receiveMethods : methods).map(m => <button type="button" key={m.value} className={method === m.value ? 'cash-method active' : 'cash-method'} onClick={() => { setMethod(m.value); setTreasuryId('') }}><span className="cash-method-icon">{m.value === 'CASH' ? '💵' : m.value === 'BANK_TRANSFER' ? '🏦' : m.value === 'CHEQUE' ? '🧾' : m.value === 'PETTY_CASH' ? '👛' : '🔁'}</span><b>{m.label}</b></button>)}</div>
            {direction === 'RECEIPT' ? <>
              {method === 'OTHER' && <div className="cash-grid cash-grid-2"><label className="cash-field"><span>شخص دریافت‌کنندهٔ وجه *</span><SearchableSelect required value={otherRecipientPartnerId} onChange={e => setOtherRecipientPartnerId(e.target.value)}><option value="">انتخاب طلبکار</option>{receiptRecipients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</SearchableSelect></label><label className="cash-field"><span>شماره پیگیری / مرجع</span><input value={reference} onChange={e => setReference(e.target.value)} maxLength={100} placeholder="در صورت وجود" /></label><p className="cash-method-hint">در روش «سایر»، مبلغ از مشتری به طلبکار او تخصیص می‌یابد و از حساب خزانه عبور نمی‌کند.</p></div>}
              {method === 'BANK_TRANSFER' && <label className="cash-field"><span>شماره پیگیری / قبض</span><input value={reference} onChange={e => setReference(e.target.value)} maxLength={100} placeholder="در صورت وجود" /></label>}
              {method === 'CHEQUE' && <div className="cash-grid cash-grid-2 cash-method-details"><label className="cash-field"><span>بانک صادرکننده *</span><SearchableSelect required value={checkDetails.bankName} onChange={e => setCheckDetails({ ...checkDetails, bankName: e.target.value })}><option value="">انتخاب بانک چک</option>{(options.checkBanks || []).map(bank => <option key={bank} value={bank}>{bank}</option>)}</SearchableSelect></label><label className="cash-field"><span>تاریخ چک *</span><JalaliDateInput className="form-control" value={checkDetails.checkDate} onChange={value => setCheckDetails({ ...checkDetails, checkDate: value })} /></label><label className="cash-field"><span>شماره چک *</span><input required value={checkDetails.checkNumber} onChange={e => setCheckDetails({ ...checkDetails, checkNumber: e.target.value })} /></label><label className="cash-field"><span>شناسهٔ صیادی چک</span><input value={checkDetails.sayadId} onChange={e => setCheckDetails({ ...checkDetails, sayadId: e.target.value })} /></label><label className="cash-field"><span>شماره حساب چک</span><input value={checkDetails.accountNumber} onChange={e => setCheckDetails({ ...checkDetails, accountNumber: e.target.value })} /></label></div>}
            </> : <>{method === 'CASH' && <div className="cash-grid cash-grid-2 cash-method-details"><label className="cash-field"><span>انتخاب صندوق *</span><SearchableSelect required value={treasuryId} onChange={e => setTreasuryId(e.target.value)}><option value="">انتخاب صندوق</option>{treasuryAccounts.filter(a => a.account_type === 'CASH').map(a => <option key={a.id} value={a.id}>{a.name} · {a.code}</option>)}</SearchableSelect></label><label className="cash-field"><span>توضیحات</span><input value={description} onChange={e => setDescription(e.target.value)} maxLength={500} placeholder="توضیحات مربوط به تسویه مستقیم" /></label><label className="cash-field cash-amount-field"><span>مبلغ تسویه *</span><div className="cash-amount-wrap"><input inputMode="numeric" required value={amount} onChange={e => setAmount(formatAmount(e.target.value))} placeholder="۰" /><span>ریال</span></div></label></div>}{method === 'PETTY_CASH' && <div className="cash-grid cash-grid-2 cash-method-details"><label className="cash-field"><span>انتخاب تنخواه *</span><SearchableSelect required value={treasuryId} onChange={e => setTreasuryId(e.target.value)}><option value="">انتخاب تنخواه</option>{treasuryAccounts.filter(a => a.account_type === 'PETTY_CASH').map(a => <option key={a.id} value={a.id}>{a.name} · {a.code}</option>)}</SearchableSelect></label><label className="cash-field"><span>توضیحات</span><input value={description} onChange={e => setDescription(e.target.value)} maxLength={500} placeholder="توضیحات مربوط به تسویه مستقیم" /></label><label className="cash-field cash-amount-field"><span>مبلغ تسویه *</span><div className="cash-amount-wrap"><input inputMode="numeric" required value={amount} onChange={e => setAmount(formatAmount(e.target.value))} placeholder="۰" /><span>ریال</span></div></label></div>}
{method === 'BANK_TRANSFER' && <div className="cash-grid cash-grid-2 cash-method-details"><label className="cash-field"><span>انتخاب بانک *</span><SearchableSelect required value={treasuryId} onChange={e => setTreasuryId(e.target.value)}><option value="">انتخاب بانک</option>{treasuryAccounts.filter(a => a.account_type === 'BANK').map(a => <option key={a.id} value={a.id}>{a.name} · {a.code}</option>)}</SearchableSelect></label><label className="cash-field"><span>توضیحات</span><input value={description} onChange={e => setDescription(e.target.value)} maxLength={500} placeholder="توضیحات مربوط به تسویه مستقیم" /></label><label className="cash-field cash-amount-field"><span>مبلغ تسویه *</span><div className="cash-amount-wrap"><input inputMode="numeric" required value={amount} onChange={e => setAmount(formatAmount(e.target.value))} placeholder="۰" /><span>ریال</span></div></label></div>}
{method === 'OTHER' && <div className="cash-grid cash-grid-2 cash-method-details"><label className="cash-field"><span>مشتری پرداخت‌کننده *</span><SearchableSelect required value={otherPaymentPartnerId} onChange={e => setOtherPaymentPartnerId(e.target.value)}><option value="">انتخاب مشتری</option>{(options.partners || []).filter(p => ['CUSTOMER', 'BOTH'].includes(p.partner_type)).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</SearchableSelect></label><label className="cash-field"><span>توضیحات</span><input value={description} onChange={e => setDescription(e.target.value)} maxLength={500} placeholder="توضیحات مربوط به تسویه مستقیم" /></label><label className="cash-field cash-amount-field"><span>مبلغ تسویه *</span><div className="cash-amount-wrap"><input inputMode="numeric" required value={amount} onChange={e => setAmount(formatAmount(e.target.value))} placeholder="۰" /><span>ریال</span></div></label></div>}{method === 'CHEQUE' && <div className="cash-method-details"><div className="cash-methods cash-methods-five"><button type="button" className={chequeSource === 'COMPANY' ? 'cash-method active' : 'cash-method'} onClick={() => { setChequeSource('COMPANY'); setCustomerChequeId('') }}><span className="cash-method-icon">🏦</span><b>دسته‌چک شرکت</b></button><button type="button" className={chequeSource === 'CUSTOMER' ? 'cash-method active' : 'cash-method'} onClick={() => { setChequeSource('CUSTOMER'); setTreasuryId(''); setCheckDetails({ bankName: '', checkNumber: '', accountNumber: '', sayadId: '', checkDate: '', ownerName: '' }) }}><span className="cash-method-icon">🧾</span><b>چک مشتری</b></button></div>{chequeSource === 'COMPANY' ? <div className="cash-grid cash-grid-2">
  <label className="cash-field"><span>انتخاب دسته‌چک *</span><SearchableSelect value={companyCheckbookId} onChange={e => { const book = companyCheckbooks.find(item => item.id === e.target.value); setCompanyCheckbookId(e.target.value); setTreasuryId(book?.treasury_account_id || ''); setCompanyCheckNumber(''); setCompanyCheckSearch(''); const bank = book?.treasuryAccount; setCheckDetails({ ...checkDetails, bankName: bank?.bank_name || bank?.name || '', checkNumber: '' }) }}><option value="">انتخاب دسته‌چک</option>{companyCheckbooks.map(book => <option key={book.id} value={book.id}>{book.name} · {book.treasuryAccount?.bank_name || book.treasuryAccount?.name} · {book.number_prefix}{String(book.number_start).padStart(book.number_width, '0')} تا {book.number_prefix}{String(book.number_end).padStart(book.number_width, '0')}</option>)}</SearchableSelect></label>
  <label className="cash-field"><span>شماره چک *</span><SearchableSelect name="company-check-number" value={companyCheckNumber} options={companyCheckNumberQuery.data || []} onChange={id => { setCompanyCheckNumber(id); setCheckDetails({ ...checkDetails, checkNumber: id }) }} onSearch={setCompanyCheckSearch} loading={companyCheckNumberQuery.isFetching} disabled={!companyCheckbookId} getOptionLabel={item => item.check_number} placeholder={companyCheckbookId ? 'شماره چک را جست‌وجو و انتخاب کنید' : 'ابتدا دسته‌چک را انتخاب کنید'} emptyLabel="شمارهٔ آزاد پیدا نشد" /></label>
  <label className="cash-field"><span>تاریخ چک *</span><JalaliDateInput className="form-control" value={checkDetails.checkDate} onChange={value => setCheckDetails({ ...checkDetails, checkDate: value })} /></label>
  <label className="cash-field"><span>شناسهٔ صیادی (اختیاری)</span><input value={checkDetails.sayadId} onChange={e => setCheckDetails({ ...checkDetails, sayadId: e.target.value })} /></label>
  <label className="cash-field cash-amount-field"><span>مبلغ پرداخت *</span><div className="cash-amount-wrap"><input inputMode="numeric" value={amount} onChange={e => setAmount(formatAmount(e.target.value))} placeholder="۰" /><span>ریال</span></div></label>
  <label className="cash-field"><span>توضیحات</span><input value={description} onChange={e => setDescription(e.target.value)} maxLength={500} placeholder="توضیحات پرداخت با چک" /></label>
</div> : <><div className="cash-grid cash-grid-2"><label className="cash-field"><span>چک نزد صندوق *</span><SearchableSelect name="held-customer-cheque" value={customerChequeId} options={heldCustomerCheques} onChange={(id, cheque) => { setCustomerChequeId(id); setAmount(cheque ? formatAmount(cheque.amount) : '') }} onSearch={setCustomerChequeSearch} loading={customerChequeQuery.isFetching} getOptionLabel={cheque => `${cheque.issuer?.name || 'مشتری'} · چک ${cheque.check_number} · ${cheque.bank_name} · ${money(cheque.amount)}`} placeholder="نام مشتری، شماره چک یا بانک را جست‌وجو کنید" emptyLabel={customerChequeSearch.trim().length < 2 ? "برای جست‌وجو دست‌کم دو نویسه وارد کنید" : "چک نزد صندوقی با این مشخصات پیدا نشد"} /></label><label className="cash-field"><span>مبلغ چک</span><div className="cash-amount-wrap"><input inputMode="numeric" readOnly value={selectedCustomerCheque ? formatAmount(selectedCustomerCheque.amount) : amount} placeholder="پس از انتخاب چک نمایش داده می‌شود" /><span>ریال</span></div></label></div>{selectedCustomerCheque && <div className="cash-check-selected"><b>{selectedCustomerCheque.issuer?.name}</b><span>{selectedCustomerCheque.bank_name} · شماره {selectedCustomerCheque.check_number}</span><span>تاریخ چک: {jalali(selectedCustomerCheque.check_date)}</span><span>شناسه صیادی: {selectedCustomerCheque.sayad_id || '—'}</span></div>}<div className="cash-grid cash-grid-2"><label className="cash-field"><span>توضیحات</span><input value={description} onChange={e => setDescription(e.target.value)} maxLength={500} placeholder="توضیحات واگذاری" /></label><label className="cash-field"><span>شماره پیگیری / مرجع</span><input value={reference} onChange={e => setReference(e.target.value)} maxLength={100} placeholder="اختیاری" /></label></div></>}</div>}</>}
            {direction === 'RECEIPT' && <div className={`cash-receive-bottom ${['CASH', 'BANK_TRANSFER', 'PETTY_CASH', 'CHEQUE'].includes(method) ? 'cash-receive-with-account' : ''}`}>
              {['CASH', 'BANK_TRANSFER', 'PETTY_CASH'].includes(method) && <label className="cash-field"><span>{method === 'CASH' ? 'صندوق *' : method === 'BANK_TRANSFER' ? 'بانک شرکت *' : 'تنخواه *'}</span><SearchableSelect value={treasuryId} onChange={e => setTreasuryId(e.target.value)}><option value="">{method === 'CASH' ? 'انتخاب صندوق' : method === 'BANK_TRANSFER' ? 'انتخاب بانک' : 'انتخاب تنخواه'}</option>{treasuryAccounts.filter(a => method === 'CASH' ? a.account_type === 'CASH' : method === 'BANK_TRANSFER' ? a.account_type === 'BANK' : a.account_type === 'PETTY_CASH').map(a => <option key={a.id} value={a.id}>{a.name} · {a.code}</option>)}</SearchableSelect></label>}
              {method !== 'CHEQUE' && method !== 'OTHER' && <label className="cash-field"><span>عنوان دریافت *</span><SearchableSelect required value={receiptCategory} onChange={e => setReceiptCategory(e.target.value)}><option value="CUSTOMER_RECEIPT">دریافت از مشتری بابت فروش</option><option value="CUSTOMER_ADVANCE">پیش‌دریافت از مشتری</option></SearchableSelect></label>}
              <label className="cash-field"><span>توضیحات (اختیاری)</span><input value={description} onChange={e => setDescription(e.target.value)} maxLength={500} placeholder="توضیحات دلخواه دربارهٔ دریافت" /></label>
              <label className="cash-field cash-amount-field"><span>مبلغ دریافت *</span><div className="cash-amount-wrap"><input inputMode="numeric" required value={amount} onChange={e => setAmount(formatAmount(e.target.value))} placeholder="۰" /><span>ریال</span></div></label>
            </div>}
            
          </section>
          <div className="cash-form-actions"><button type="submit" className="cash-submit" disabled={create.isPending || directCreate.isPending || customerChequeCreate.isPending || issueCompanyCheque.isPending || optionsQuery.isLoading || companyCheckbooksQuery.isLoading}>{create.isPending || directCreate.isPending || customerChequeCreate.isPending || issueCompanyCheque.isPending ? <span className="spinner" /> : <><FiPlus /> {direction === 'RECEIPT' ? 'ثبت دریافت' : 'ثبت ' + config.title}</>}</button><button type="button" className="cash-reset" onClick={resetForm}>پاک‌سازی فرم</button><span>میانبر ثبت: Ctrl+S</span></div>
        </form> : <form className="cash-card cash-form" onSubmit={submitDirect}><section className="cash-section"><div className="cash-section-title"><span>۱</span><b>انتخاب طرف‌حساب‌ها</b></div><div className="cash-grid cash-grid-2"><label className="cash-field"><span>مشتری بدهکار *</span><SearchableSelect value={directCustomerId} onChange={e => setDirectCustomerId(e.target.value)}><option value="">انتخاب مشتری</option>{directOptions.customers.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</SearchableSelect></label><label className="cash-field"><span>تأمین‌کنندهٔ طلبکار *</span><SearchableSelect value={directSupplierId} onChange={e => setDirectSupplierId(e.target.value)}><option value="">انتخاب تأمین‌کننده</option>{directOptions.suppliers.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</SearchableSelect></label><label className="cash-field"><span>تاریخ سند *</span><JalaliDateInput className="form-control" value={directDate} onChange={setDirectDate} /></label></div></section><section className="cash-section"><div className="cash-section-title"><span>۲</span><b>مبلغ و شرح</b></div><div className="cash-method-hint cash-method-hint-warn">وجهی از خزانه عبور نمی‌کند؛ مبلغ از فاکتورهای باز دو طرف تخصیص داده می‌شود.</div><label className="cash-field cash-amount-field"><span>مبلغ تسویه *</span><div className="cash-amount-wrap"><input inputMode="numeric" value={directAmount} onChange={e => setDirectAmount(formatAmount(e.target.value))} placeholder="۰" /><span>ریال</span></div></label><label className="cash-field"><span>شماره پیگیری / مرجع</span><input value={directReference} onChange={e => setDirectReference(e.target.value)} maxLength={100} /></label><label className="cash-field"><span>شرح سند *</span><textarea rows="3" value={directDescription} onChange={e => setDirectDescription(e.target.value)} maxLength={500} /></label></section><div className="cash-form-actions"><button type="submit" className="cash-submit" disabled={directCreate.isPending || directOptionsQuery.isLoading}>{directCreate.isPending ? <span className="spinner" /> : <><FiPlus /> ثبت تسویهٔ مستقیم</>}</button><span>میانبر ثبت: Ctrl+S</span></div></form>}
        <aside className="cash-card cash-summary"><div className="cash-summary-head"><h2>خلاصه سند</h2><span className="cash-summary-status">{(showSettlementPreview ? directAmount : amount) ? 'آماده بررسی' : 'در انتظار مبلغ'}</span></div>{showSettlementPreview ? <><div className="cash-summary-row"><span>مشتری بدهکار</span><b>{directOptions.customers.find(p => p.id === directCustomerId)?.name || '—'}</b></div><div className="cash-summary-row"><span>تأمین‌کننده طلبکار</span><b>{directOptions.suppliers.find(p => p.id === directSupplierId)?.name || '—'}</b></div><div className="cash-summary-divider" /><div className="cash-summary-total"><span>مبلغ تسویه</span><b>{money(asciiDigits(directAmount).replace(/[^0-9]/g, ''))}</b></div><p className="cash-summary-note">ثبت سند، ماندهٔ فاکتورهای باز دو طرف را اصلاح می‌کند.</p></> : <><div className="cash-summary-row"><span>{direction === 'PAYMENT' ? 'طرف‌حساب / حساب هزینه' : 'طرف‌حساب'}</span><b>{direction === 'PAYMENT' ? (paymentTarget.startsWith('ACCOUNT:') ? paymentAccounts.find(a => a.id === paymentTarget.slice(8))?.name || '—' : options.partners?.find(p => p.id === paymentTarget.slice(8))?.name || '—') : options.partners?.find(p => p.id === partnerId)?.name || '—'}</b></div><div className="cash-summary-row"><span>روش</span><b>{methodOptions.find(m => m.value === method)?.label || '—'}</b></div><div className="cash-summary-row"><span>{direction === 'RECEIPT' ? (method === 'OTHER' ? 'شخص دریافت‌کننده' : 'حساب دریافت') : (method === 'OTHER' ? 'طرف‌حساب پرداخت‌کننده' : 'حساب خزانه')}</span><b>{direction === 'RECEIPT' ? (method === 'OTHER' ? receiptRecipients.find(p => p.id === otherRecipientPartnerId)?.name || '—' : selectedTreasury?.name || '—') : (method === 'OTHER' ? options.partners?.find(p => p.id === otherPaymentPartnerId)?.name || '—' : selectedTreasury?.name || '—')}</b></div><div className="cash-summary-divider" /><div className="cash-summary-total"><span>مبلغ {config.positive}</span><b>{money(asciiDigits(amount).replace(/[^0-9]/g, ''))}</b></div><p className="cash-summary-note">{method === 'OTHER' ? 'ماندهٔ فاکتورهای باز اصلاح می‌شود؛ سند خزانه ثبت نمی‌شود.' : 'گردش خزانه و دفتر کل پس از ثبت به‌روزرسانی می‌شود.'}</p></>}</aside>
      </div>
      <section className="cash-card cash-list"><div className="cash-list-heading"><h2>{showSettlementPreview ? 'تسویه‌های مستقیم ثبت‌شده' : config.title + '‌های ثبت‌شده'}</h2><span>{faNumber(showSettlementPreview ? directListQuery.data?.pagination?.totalItems : listQuery.data?.pagination?.totalItems)} سند</span></div>{!canRead ? <div className="error-state"><FiAlertCircle /><strong>دسترسی به این بخش ندارید</strong></div> : showSettlementPreview ? (directListQuery.isLoading ? <div className="loading-line" /> : directListQuery.isError ? <div className="error-state"><FiAlertCircle />{getErrorMessage(directListQuery.error)}</div> : <div className="table-scroll"><table className="data-table"><thead><tr><th>شماره سند</th><th>تاریخ</th><th>مشتری</th><th>تأمین‌کننده</th><th>شرح</th><th>مبلغ</th><th>وضعیت</th></tr></thead><tbody>{directRows.map(row => <tr key={row.id}><td>{row.voucher_no}</td><td>{jalali(row.entry_date)}</td><td>{row.customer?.name || '—'}</td><td>{row.supplier?.name || '—'}</td><td>{row.description || '—'}</td><td className="number-cell">{money(row.amount)}</td><td>{row.reverses_settlement_id ? 'سند معکوس' : row.reversal ? 'برگشت شده' : canReverse ? <button className="btn btn-secondary" onClick={() => { setReverseDirectSelected(row); setReverseDate(localToday()) }}><FiRotateCcw /> برگشت</button> : 'ثبت‌شده'}</td></tr>)}{!directRows.length && <tr><td colSpan="7"><div className="empty-state">هنوز سندی ثبت نشده است.</div></td></tr>}</tbody></table></div>) : (listQuery.isLoading ? <div className="loading-line" /> : listQuery.isError ? <div className="error-state"><FiAlertCircle />{getErrorMessage(listQuery.error)}</div> : <div className="table-scroll"><table className="data-table"><thead><tr><th>شماره سند</th><th>تاریخ</th><th>طرف حساب</th><th>حساب مقابل</th><th>خزانه</th><th>روش</th><th>شرح</th><th>مبلغ</th><th>وضعیت</th></tr></thead><tbody>{rows.map(row => <tr key={row.id}><td>{row.voucher_no}</td><td>{jalali(row.entry_date)}</td><td>{row.partner?.name || '—'}</td><td>{row.reverses_voucher_id ? 'برگشت سند' : direction === 'PAYMENT' ? [row.counterpartAccount?.name, row.partner?.name].filter(Boolean).join(' · ') || '—' : categoryOptions.find(x => x.value === row.category)?.label || row.category}</td><td>{row.treasuryAccount?.name || '—'}</td><td>{row.method === 'CASH' && row.treasuryAccount?.account_type === 'PETTY_CASH' ? 'تنخواه' : methods.find(x => x.value === row.method)?.label || row.method}</td><td>{row.description || '—'}</td><td className="number-cell">{money(row.amount)}</td><td>{row.reverses_voucher_id ? 'سند معکوس' : row.reversal ? 'برگشت شده' : canReverse ? <button className="btn btn-secondary" onClick={() => { setReverseSelected(row); setReverseDate(localToday()) }}><FiRotateCcw /> برگشت</button> : 'ثبت‌شده'}</td></tr>)}{!rows.length && <tr><td colSpan="9"><div className="empty-state">هنوز سندی ثبت نشده است.</div></td></tr>}</tbody></table></div>)}</section>{!showChequeRegistry && <div className="table-footer"><span>صفحهٔ {faNumber(page)} از {faNumber(Math.max(1, (showSettlementPreview ? directListQuery.data?.pagination?.totalPages : listQuery.data?.pagination?.totalPages) || 1))}</span><div className="pagination"><button disabled={page <= 1} onClick={() => setPage(value => value - 1)}>صفحهٔ قبل</button><button disabled={page >= ((showSettlementPreview ? directListQuery.data?.pagination?.totalPages : listQuery.data?.pagination?.totalPages) || 1)} onClick={() => setPage(value => value + 1)}>صفحهٔ بعد</button></div></div>}      {reverseSelected && <div className="modal-backdrop" onMouseDown={e => e.target === e.currentTarget && setReverseSelected(null)}><section className="modal-card"><div className="modal-heading"><div><span className="eyebrow">اصلاح سند مالی</span><h2>برگشت سند {reverseSelected.voucher_no}</h2></div><button className="icon-button" onClick={() => setReverseSelected(null)}><FiX /></button></div><form className="modal-form" onSubmit={e => { e.preventDefault(); if (reverseReason.trim().length < 2) { toast.error('دلیل برگشت را وارد کنید'); return } reverse.mutate() }}><p>سند معکوس برای {money(reverseSelected.amount)} ثبت می‌شود.</p><label className="form-field"><span>تاریخ برگشت *</span><JalaliDateInput className="form-control" value={reverseDate} onChange={setReverseDate} /></label><label className="form-field"><span>دلیل برگشت *</span><textarea className="form-control" value={reverseReason} onChange={e => setReverseReason(e.target.value)} /></label><div className="modal-actions"><button type="button" className="btn btn-secondary" onClick={() => setReverseSelected(null)}>انصراف</button><button type="submit" className="btn btn-primary" disabled={reverse.isPending}>ثبت سند معکوس</button></div></form></section></div>}
      {reverseDirectSelected && <div className="modal-backdrop" onMouseDown={e => e.target === e.currentTarget && setReverseDirectSelected(null)}><section className="modal-card"><div className="modal-heading"><div><span className="eyebrow">اصلاح سند مالی</span><h2>برگشت تسویه {reverseDirectSelected.voucher_no}</h2></div><button className="icon-button" onClick={() => setReverseDirectSelected(null)}><FiX /></button></div><form className="modal-form" onSubmit={e => { e.preventDefault(); if (reverseReason.trim().length < 2) { toast.error('دلیل برگشت را وارد کنید'); return } reverseDirect.mutate() }}><p>برگشت سند، ماندهٔ دو طرف‌حساب را اصلاح می‌کند.</p><label className="form-field"><span>تاریخ برگشت *</span><JalaliDateInput className="form-control" value={reverseDate} onChange={setReverseDate} /></label><label className="form-field"><span>دلیل برگشت *</span><textarea className="form-control" value={reverseReason} onChange={e => setReverseReason(e.target.value)} /></label><div className="modal-actions"><button type="button" className="btn btn-secondary" onClick={() => setReverseDirectSelected(null)}>انصراف</button><button type="submit" className="btn btn-primary" disabled={reverseDirect.isPending}>ثبت برگشت</button></div></form></section></div>}
    </section>
  )
}

